function listPage(type){let list=[...contacts],title='Tous les contacts',sub='Votre base de contacts centralisée.';if(type==='pistes'){list=list.filter(c=>!['Converti','Disqualifié'].includes(c.statut));title='Pipeline des pistes';sub='Pilotez vos opportunités et le financement de chaque candidat.'}if(type==='inscrits'){list=list.filter(c=>c.statut==='Converti');title='Inscrits';sub='Les candidats convertis et inscrits en formation.'}if(type==='relances'){list=list.filter(c=>c.statut==='A relancer').sort((a,b)=>(a.relance_date||'9999').localeCompare(b.relance_date||'9999'));title='Relances';sub='Toutes les personnes à recontacter, classées par date.'}if(statusFilter)list=list.filter(c=>c.statut===statusFilter);const kpis=type==='pistes'?`<div class="status-grid">${S.map(s=>`<button class="status-kpi ${statusFilter===s?'active':''}" data-status="${s}"><b>${contacts.filter(c=>c.statut===s).length}</b><span>${s}</span></button>`).join('')}</div>`:'';return header('RELATION CLIENT',title,sub)+kpis+`<div class="filters"><input id="listSearch" placeholder="⌕  Rechercher…"><select id="formationFilter"><option value="">Toutes les formations</option>${['APS','A3P','DESP','SSIAP 1','Chauffeur VTC'].map(x=>`<option>${x}</option>`).join('')}</select><select id="lieuFilter"><option value="">Tous les lieux</option><option>Paris</option><option>Côte d’Azur</option></select></div><div id="resultTable">${table(list)}</div>`}
