function selectHtml(n,l,c){return `<label>${l}</label><div class="binary-choice" role="radiogroup" aria-label="${esc(l)}"><label><input type="radio" name="${n}" value="OUI" ${c[n]==='OUI'?'checked':''}>OUI</label><label><input type="radio" name="${n}" value="NON" ${c[n]==='NON'?'checked':''}>NON</label></div>`}function selectField(n,l,c){return `<div class="field">${selectHtml(n,l,c)}</div>`}function feed(c,expanded=false){const activities=c.activities||[],visible=expanded?activities:activities.slice(0,5);return visible.map(a=>`<div class="feed-item"><span class="feed-icon">${a.kind==='appel'?'☎':a.kind==='email'?'✉':a.kind==='sms'?'▣':a.kind==='calendly'?'◷':'◆'}</span><div><b>${esc(a.title)}</b><p>${esc(a.detail)}</p><time>${fmt(a.date)} · ${esc(a.author)}</time>${a.preview?`<br><a class="preview-link" data-preview="${encodeURIComponent(a.preview)}">Prévisualiser</a>`:''}</div></div>`).join('')+(activities.length>5&&!expanded?`<button class="btn feed-more" id="feedMore">Voir plus (${activities.length-5})</button>`:'')||'<div class="empty">Aucune activité</div>'}
