  const more=document.querySelector('#feedMore');if(more)more.onclick=()=>{activityFeed.innerHTML=feed(c,true);document.querySelectorAll('[data-preview]').forEach(a=>a.onclick=()=>previewModal(decodeURIComponent(a.dataset.preview)))};
